'use client';

import React from 'react';

/** Voice session status. */
export type VoiceSessionStatus = 'idle' | 'listening' | 'transcribing' | 'speaking' | 'handoff';

/** A single transcript turn. */
export interface VoiceTranscriptTurn {
  /** Role of the speaker. */
  role: 'user' | 'assistant';
  /** Transcript text content. */
  text: string;
}

/** Number of placeholder waveform bars rendered when no `waveform` data is supplied. */
const DEFAULT_WAVEFORM_BARS = 8;

/** Props for the {@link VoiceSession} component. */
export interface VoiceSessionProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current session status. */
  status?: VoiceSessionStatus;
  /** Elapsed time string (e.g. "00:42"). */
  clock?: string;
  /** Array of waveform bar heights (0-1 normalized). Omit to render animated placeholder bars. */
  waveform?: number[];
  /** Transcript turns. */
  transcript?: VoiceTranscriptTurn[];
  /** Accessible label for the region landmark. */
  label?: string;
  /** Called when the built-in Mute control is clicked. Renders the Mute button when provided. */
  onMute?: () => void;
  /** Called when the built-in End control is clicked. Renders the End button when provided. */
  onEnd?: () => void;
  /** Visible text for the Mute control. */
  muteLabel?: string;
  /** Visible text for the End control. */
  endLabel?: string;
  /** Additional CSS class names. */
  className?: string;
  /** Extra control elements rendered alongside the built-in Mute/End buttons. */
  children?: React.ReactNode;
}

/**
 * Realtime voice session with waveform, transcript, and state indicators.
 * Renders a `<div>` with `sk-voice-session` and `data-status`.
 *
 * The waveform animates via CSS (`@keyframes sk-voice-bar`) while
 * `status` is `listening` or `speaking` — no JavaScript ticking required.
 */
export const VoiceSession = React.forwardRef<HTMLDivElement, VoiceSessionProps>(
  (
    {
      status = 'idle',
      clock,
      waveform,
      transcript,
      label = 'Voice session',
      onMute,
      onEnd,
      muteLabel = 'Mute',
      endLabel = 'End',
      className,
      children,
      ...rest
    },
    ref,
  ) => {
    // Render supplied bar heights, or a default set so the CSS animation has something to drive.
    const bars =
      waveform && waveform.length > 0
        ? waveform.map((h) => `${Math.max(2, h * 32)}px`)
        : Array.from({ length: DEFAULT_WAVEFORM_BARS }, () => undefined);
    const hasControls = Boolean(onMute || onEnd || children);

    return (
      <div
        ref={ref}
        className={`sk-voice-session${className ? ` ${className}` : ''}`}
        data-status={status}
        role="region"
        aria-label={label}
        {...rest}
      >
        {clock && <div className="sk-voice-session__clock">{clock}</div>}
        <div className="sk-voice-session__waveform" aria-hidden="true">
          {bars.map((height, i) => (
            <div
              key={i}
              className="sk-voice-session__waveform-bar"
              style={height ? { height } : undefined}
            />
          ))}
        </div>
        {transcript && transcript.length > 0 && (
          <div className="sk-voice-session__transcript" aria-live="polite">
            {transcript.map((turn, i) => (
              <div key={i} className="sk-voice-session__turn" data-role={turn.role}>
                {turn.text}
              </div>
            ))}
          </div>
        )}
        {hasControls && (
          <div className="sk-voice-session__controls">
            {onMute && (
              <button
                type="button"
                className="sk-voice-session__control"
                data-action="mute"
                onClick={onMute}
                aria-label="Mute microphone"
              >
                {muteLabel}
              </button>
            )}
            {onEnd && (
              <button
                type="button"
                className="sk-voice-session__control"
                data-action="end"
                onClick={onEnd}
                aria-label="End session"
              >
                {endLabel}
              </button>
            )}
            {children}
          </div>
        )}
      </div>
    );
  },
);

VoiceSession.displayName = 'VoiceSession';

/**
 * skeehn — VoiceSession Component
 *
 * @component sk-voice-session
 * @statuses  idle | listening | transcribing | speaking | handoff
 * @slots     __clock __waveform __waveform-bar __transcript __turn __controls
 * @a11y      aria-live transcript, status via text + color
 * @design    Denser waveform, readable transcript turns w/ speaker tint, accent states.
 */

.sk-voice-session {
  /* Waveform geometry — token-rooted so bars stay consistent with the scale.
     --sk-voice-bar-rest/peak are the heights the CSS animation oscillates between. */
  --sk-voice-bar-width: var(--sk-space-1);
  --sk-voice-bar-gap: calc(var(--sk-space-1) / 2);
  --sk-voice-bar-rest: 18%;
  --sk-voice-bar-peak: 100%;
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); line-height: var(--sk-line-height);
  color: hsl(var(--sk-foreground)); background: hsl(var(--sk-surface));
  border: var(--sk-border); border-radius: var(--sk-radius-md);
  padding: var(--sk-space-4); display: flex; flex-direction: column; gap: var(--sk-space-3);
  transition: border-color var(--sk-transition);
}
.sk-voice-session[data-status="idle"] { opacity: 0.75; }
.sk-voice-session[data-status="listening"]    { border-color: hsl(var(--sk-accent)); }
.sk-voice-session[data-status="transcribing"] { border-color: hsl(var(--sk-info)); }
.sk-voice-session[data-status="speaking"]     { border-color: hsl(var(--sk-success)); }
.sk-voice-session[data-status="handoff"]      { opacity: 0.5; }

.sk-voice-session__clock { font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); color: hsl(var(--sk-muted-foreground)); letter-spacing: var(--sk-letter-spacing-xwide); font-variant-numeric: tabular-nums; }

/* Waveform — denser bars */
.sk-voice-session__waveform { display: flex; align-items: center; gap: var(--sk-voice-bar-gap); height: var(--sk-size-avatar-md); }
.sk-voice-session__waveform-bar {
  width: var(--sk-voice-bar-width);
  height: var(--sk-voice-bar-rest);
  min-height: var(--sk-voice-bar-width);
  background: hsl(var(--sk-foreground));
  border-radius: var(--sk-radius-full);
  transition: height var(--sk-transition-fast);
  transform-origin: center;
}
.sk-voice-session[data-status="speaking"] .sk-voice-session__waveform-bar { background: hsl(var(--sk-success)); }

/* CSS-only animated waveform — bars oscillate while listening/speaking, no JS required.
   Staggered per-bar delays give the classic rolling waveform read. */
@keyframes sk-voice-bar {
  0%, 100% { height: var(--sk-voice-bar-rest); }
  50%      { height: var(--sk-voice-bar-peak); }
}
.sk-voice-session[data-status="listening"] .sk-voice-session__waveform-bar,
.sk-voice-session[data-status="speaking"]  .sk-voice-session__waveform-bar {
  animation: sk-voice-bar 0.9s ease-in-out infinite;
}
.sk-voice-session__waveform-bar:nth-child(1) { animation-delay: 0s; }
.sk-voice-session__waveform-bar:nth-child(2) { animation-delay: 0.12s; }
.sk-voice-session__waveform-bar:nth-child(3) { animation-delay: 0.24s; }
.sk-voice-session__waveform-bar:nth-child(4) { animation-delay: 0.36s; }
.sk-voice-session__waveform-bar:nth-child(5) { animation-delay: 0.30s; }
.sk-voice-session__waveform-bar:nth-child(6) { animation-delay: 0.18s; }
.sk-voice-session__waveform-bar:nth-child(7) { animation-delay: 0.42s; }
.sk-voice-session__waveform-bar:nth-child(8) { animation-delay: 0.06s; }

/* Transcript */
.sk-voice-session__transcript { display: flex; flex-direction: column; gap: var(--sk-space-2); max-height: 12rem; overflow-y: auto; }
.sk-voice-session__turn {
  font-family: var(--sk-font-sans); font-size: var(--sk-font-size-sm);
  color: hsl(var(--sk-foreground)); line-height: var(--sk-line-height-relaxed);
  padding: var(--sk-space-2) var(--sk-space-3); border-left: 2px solid hsl(var(--sk-border-color));
  border-radius: 0 var(--sk-radius-sm) var(--sk-radius-sm) 0;
}
.sk-voice-session__turn[data-role="user"] { border-left-color: hsl(var(--sk-accent)); background: hsl(var(--sk-accent) / 0.06); }
.sk-voice-session__turn[data-role="assistant"] { border-left-color: hsl(var(--sk-muted-foreground) / 0.4); background: hsl(var(--sk-muted) / 0.4); }

.sk-voice-session__controls { display: flex; gap: var(--sk-space-2); align-items: center; }

/* Built-in controls (mute/end). Inherit btn styling when .sk-btn is present;
   these rules keep standalone controls coherent and accessible on their own. */
.sk-voice-session__control {
  font: inherit;
  letter-spacing: var(--sk-letter-spacing-wide);
  padding: var(--sk-space-1) var(--sk-space-3);
  color: hsl(var(--sk-foreground));
  background: transparent;
  border: var(--sk-border);
  border-radius: var(--sk-radius-control);
  cursor: pointer;
  transition: color var(--sk-transition), background var(--sk-transition), border-color var(--sk-transition);
}
.sk-voice-session__control:hover { background: hsl(var(--sk-secondary)); border-color: hsl(var(--sk-foreground) / 0.3); }
.sk-voice-session__control[data-action="end"] { color: hsl(var(--sk-destructive)); }
.sk-voice-session__control:focus-visible { outline: var(--sk-focus-ring); outline-offset: var(--sk-focus-ring-offset); }

/* Loading & skeleton */
.sk-voice-session[data-loading] { pointer-events: none; opacity: 0.6; }
.sk-voice-session[data-loading] .sk-voice-session__waveform { opacity: 0.3; }
.sk-voice-session[data-skeleton] .sk-voice-session__waveform,
.sk-voice-session[data-skeleton] .sk-voice-session__transcript,
.sk-voice-session[data-skeleton] .sk-voice-session__clock {
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius-sm); color: transparent;
}
.sk-voice-session[data-skeleton] .sk-voice-session__waveform-bar { display: none; }
.sk-voice-session[data-skeleton] .sk-voice-session__turn { visibility: hidden; }

@media print {
  .sk-voice-session { border: var(--sk-border-width) solid hsl(var(--sk-foreground)); }
  .sk-voice-session__controls, .sk-voice-session__clock { display: none; }
  /* Waveform prints as a frozen, static-height snapshot (no animation). */
  .sk-voice-session[data-status="listening"] .sk-voice-session__waveform-bar,
  .sk-voice-session[data-status="speaking"]  .sk-voice-session__waveform-bar { animation: none; height: var(--sk-voice-bar-rest); }
  .sk-voice-session[data-skeleton] { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  /* Hold bars at a static height instead of oscillating. */
  .sk-voice-session__waveform-bar { transition: none; }
  .sk-voice-session[data-status="listening"] .sk-voice-session__waveform-bar,
  .sk-voice-session[data-status="speaking"]  .sk-voice-session__waveform-bar { animation: none; height: var(--sk-voice-bar-rest); }
  .sk-voice-session[data-skeleton] .sk-voice-session__waveform,
  .sk-voice-session[data-skeleton] .sk-voice-session__transcript,
  .sk-voice-session[data-skeleton] .sk-voice-session__clock { animation: none; background: hsl(var(--sk-muted)); }
}
